3	const NUM = '0|[1-9]\\d{0,256}'
4	const NUMLOOSE = '\\d{1,256}'
5	const NONNUM = '\\d{0,256}[a-zA-Z-][a-zA-Z0-9-]{0,250}'
6	const PREID = '(?:' + NONNUM + '|' + NUM + ')'
7	const PREIDLOOSE = '(?:' + NONNUM + '|' + NUMLOOSE + ')'
8	const PRE = '(?:-(' + PREID + '(?:\\.' + PREID + ')*))'
9	const PRELOOSE = '(?:-?(' + PREIDLOOSE + '(?:\\.' + PREIDLOOSE + ')*))'
10	const BUILD = '(?:\\+([a-zA-Z0-9-]{1,250}(?:\\.[a-zA-Z0-9-]{1,250})*))'
11	const FULLPLAIN = 'v?(' + NUM + ')\\.(' + NUM + ')\\.(' + NUM + ')' + PRE + '?' + BUILD + '?'
12	const LOOSEPLAIN = '[v=\\s]*(' + NUMLOOSE + ')\\.(' + NUMLOOSE + ')\\.(' + NUMLOOSE + ')' + PRELOOSE + '?' + BUILD + '?'
13	
14	const XID = NUM + '|x|X|\\*'
15	const XIDLOOSE = NUMLOOSE + '|x|X|\\*'
16	const XRANGEPLAIN = '[v=\\s]*(' + XID + ')(?:\\.(' + XID + ')(?:\\.(' + XID + ')(?:' + PRE + ')?' + BUILD + '?)?)?'
17	const XRANGEPLAINLOOSE = '[v=\\s]*(' + XIDLOOSE + ')(?:\\.(' + XIDLOOSE + ')(?:\\.(' + XIDLOOSE + ')(?:' + PRELOOSE + ')?' + BUILD + '?)?)?'
18	
19	const HYPHEN_RE = new RegExp('^\\s{0,1}(' + XRANGEPLAIN + ')\\s{1,1}-\\s{1,1}(' + XRANGEPLAIN + ')\\s{0,1}$')
20	const HYPHENLOOSE_RE = new RegExp('^\\s{0,1}(' + XRANGEPLAINLOOSE + ')\\s{1,1}-\\s{1,1}(' + XRANGEPLAINLOOSE + ')\\s{0,1}$')
21	const COMPTRIM_RE = new RegExp('(\\s{0,1})((?:<|>)?=?)\\s{0,1}(' + LOOSEPLAIN + '|' + XRANGEPLAIN + ')', 'g')
22	const TILDETRIM_RE = /(\s{0,1})(?:~>?)\s{1,1}/g
23	const CARETTRIM_RE = /(\s{0,1})(?:\^)\s{1,1}/g
24	const TILDE_RE = new RegExp('^(?:~>?)' + XRANGEPLAIN + '$')
25	const TILDELOOSE_RE = new RegExp('^(?:~>?)' + XRANGEPLAINLOOSE + '$')
26	const CARET_RE = new RegExp('^(?:\\^)' + XRANGEPLAIN + '$')
27	const CARETLOOSE_RE = new RegExp('^(?:\\^)' + XRANGEPLAINLOOSE + '$')
28	const XRANGE_RE = new RegExp('^((?:<|>)?=?)\\s{0,1}' + XRANGEPLAIN + '$')
29	const XRANGELOOSE_RE = new RegExp('^((?:<|>)?=?)\\s{0,1}' + XRANGEPLAINLOOSE + '$')
30	const COMPARATORLOOSE_RE = new RegExp('^((?:<|>)?=?)\\s{0,1}(' + LOOSEPLAIN + ')$|^$')
31	const BUILD_RE = new RegExp(BUILD)
32	// unbounded global build-metadata stripper used by parseRange
33	const BUILDSTRIP_RE = /(?:\+([a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*))/g
34	
35	// parsed ranges, oldest first, at most 1000
36	const rangeCache = new Map()
37	
38	// hoisted class for cyclic dependency
39	class Range {
40	  constructor (range, options) {
41	    if (!options) {
42	      options = Object.freeze({})
43	    } else if (typeof options !== 'object') {
44	      options = Object.freeze({ loose: true })
45	    }
46	
47	    if (range instanceof Range) {
48	      if (
49	        range.loose === !!options.loose &&
50	        range.includePrerelease === !!options.includePrerelease
51	      ) {
52	        return range
53	      } else {
54	        return new Range(range.raw, options)
55	      }
56	    }
57	
58	    if (range instanceof Comparator) {
59	      // just put it in the set and return
60	      this.raw = range.value
61	      this.set = [[range]]
62	      this.formatted = undefined
63	      return this
64	    }
65	
66	    this.options = options
67	    this.loose = !!options.loose
68	    this.includePrerelease = !!options.includePrerelease
69	
70	    // First reduce all whitespace as much as possible so we do not have to rely
71	    // on potentially slow regexes like \s*. This is then stored and used for
72	    // future error messages as well.
73	    this.raw = range.trim().replace(/\s+/g, ' ')
74	
75	    // split on ||, parse each part, throw out the empty ones
76	    const set = []
77	    for (const part of this.raw.split('||')) {
78	      const comps = this.parseRange(part.trim())
79	      if (comps.length) {
80	        set.push(comps)
81	      }
82	    }
83	    this.set = set
84	
85	    if (!this.set.length) {
86	      throw new TypeError(`Invalid SemVer Range: ${this.raw}`)
87	    }
88	
89	    // if we have any that are not the null set, throw out null sets.
90	    if (this.set.length > 1) {
91	      // keep the first one, in case they're all null sets
92	      const first = this.set[0]
93	      this.set = this.set.filter(c => c[0].value !== '<0.0.0-0')
94	      if (this.set.length === 0) {
95	        this.set = [first]
96	      } else if (this.set.length > 1) {
97	        // if we have any that are *, then the range is just *
98	        for (const c of this.set) {
99	          if (c.length === 1 && c[0].value === '') {
100	            this.set = [c]
101	            break
102	          }
103	        }
104	      }
105	    }
106	
107	    this.formatted = undefined
108	  }
109	
110	  get range () {
111	    if (this.formatted === undefined) {
112	      this.formatted = ''
113	      for (let i = 0; i < this.set.length; i++) {
114	        if (i > 0) {
115	          this.formatted += '||'
116	        }
117	        const comps = this.set[i]
118	        for (let k = 0; k < comps.length; k++) {
119	          if (k > 0) {
120	            this.formatted += ' '
121	          }
122	          this.formatted += comps[k].toString().trim()
123	        }
124	      }
125	    }
126	    return this.formatted
127	  }
128	
129	  format () {
130	    return this.range
131	  }
132	
133	  toString () {
134	    return this.range
135	  }
136	
137	  parseRange (range) {
138	    // strip build metadata so it can't bleed into the version
139	    range = range.replace(BUILDSTRIP_RE, '')
140	
141	    // memoize range parsing for performance.
142	    // this is a very hot path, and fully deterministic.
143	    const memoKey = ((this.options.includePrerelease && 1) | (this.options.loose && 2)) + ':' + range
144	    const cached = rangeCache.get(memoKey)
145	    if (cached !== undefined) {
146	      rangeCache.delete(memoKey)
147	      rangeCache.set(memoKey, cached)
148	      return cached
149	    }
150	
151	    const loose = this.options.loose
152	    const incPr = this.options.includePrerelease
153	
154	    // `1.2.3 - 1.2.4` => `>=1.2.3 <=1.2.4`
155	    range = range.replace(loose ? HYPHENLOOSE_RE : HYPHEN_RE, ($0, from, fM, fm, fp, fpr, fb, to, tM, tm, tp, tpr) => {
156	      if (!fM || fM.toLowerCase() === 'x' || fM === '*') {
157	        from = ''
158	      } else if (!fm || fm.toLowerCase() === 'x' || fm === '*') {
159	        from = `>=${fM}.0.0${incPr ? '-0' : ''}`
160	      } else if (!fp || fp.toLowerCase() === 'x' || fp === '*') {
161	        from = `>=${fM}.${fm}.0${incPr ? '-0' : ''}`
162	      } else if (fpr) {
163	        from = `>=${from}`
164	      } else {
165	        from = `>=${from}${incPr ? '-0' : ''}`
166	      }
167	
168	      if (!tM || tM.toLowerCase() === 'x' || tM === '*') {
169	        to = ''
170	      } else if (!tm || tm.toLowerCase() === 'x' || tm === '*') {
171	        to = `<${+tM + 1}.0.0-0`
172	      } else if (!tp || tp.toLowerCase() === 'x' || tp === '*') {
173	        to = `<${tM}.${+tm + 1}.0-0`
174	      } else if (tpr) {
175	        to = `<=${tM}.${tm}.${tp}-${tpr}`
176	      } else if (incPr) {
177	        to = `<${tM}.${tm}.${+tp + 1}-0`
178	      } else {
179	        to = `<=${to}`
180	      }
181	
182	      return `${from} ${to}`.trim()
183	    })
184	
185	    // `> 1.2.3 < 1.2.5` => `>1.2.3 <1.2.5`
186	    range = range.replace(COMPTRIM_RE, '$1$2$3')
187	    // `~ 1.2.3` => `~1.2.3`
188	    range = range.replace(TILDETRIM_RE, '$1~')
189	    // `^ 1.2.3` => `^1.2.3`
190	    range = range.replace(CARETTRIM_RE, '$1^')
191	
192	    // At this point, the range is completely trimmed and
193	    // ready to be split into comparators.
194	    const z = incPr ? '-0' : ''
195	    const parts = []
196	    for (let comp of range.split(' ')) {
197	      comp = comp.replace(BUILD_RE, '')
198	
199	      // ^ --> * (any, kinda silly)
200	      // ^2, ^2.x, ^2.x.x --> >=2.0.0 <3.0.0-0
201	      // ^2.0, ^2.0.x --> >=2.0.0 <3.0.0-0
202	      // ^1.2, ^1.2.x --> >=1.2.0 <2.0.0-0
203	      // ^1.2.3 --> >=1.2.3 <2.0.0-0
204	      // ^1.2.0 --> >=1.2.0 <2.0.0-0
205	      // ^0.0.1 --> >=0.0.1 <0.0.2-0
206	      // ^0.1.0 --> >=0.1.0 <0.2.0-0
207	      comp = comp.trim().split(/\s+/).map((c) => c.replace(loose ? CARETLOOSE_RE : CARET_RE, (_, M, m, p, pr) => {
208	        let ret
209	        if (!M || M.toLowerCase() === 'x' || M === '*') {
210	          ret = ''
211	        } else if (!m || m.toLowerCase() === 'x' || m === '*') {
212	          ret = `>=${M}.0.0${z} <${+M + 1}.0.0-0`
213	        } else if (!p || p.toLowerCase() === 'x' || p === '*') {
214	          if (M === '0') {
215	            ret = `>=${M}.${m}.0${z} <${M}.${+m + 1}.0-0`
216	          } else {
217	            ret = `>=${M}.${m}.0${z} <${+M + 1}.0.0-0`
218	          }
219	        } else if (pr) {
220	          if (M === '0') {
221	            if (m === '0') {
222	              ret = `>=${M}.${m}.${p}-${pr} <${M}.${m}.${+p + 1}-0`
223	            } else {
224	              ret = `>=${M}.${m}.${p}-${pr} <${M}.${+m + 1}.0-0`
225	            }
226	          } else {
227	            ret = `>=${M}.${m}.${p}-${pr} <${+M + 1}.0.0-0`
228	          }
229	        } else {
230	          if (M === '0') {
231	            if (m === '0') {
232	              ret = `>=${M}.${m}.${p} <${M}.${m}.${+p + 1}-0`
233	            } else {
234	              ret = `>=${M}.${m}.${p} <${M}.${+m + 1}.0-0`
235	            }
236	          } else {
237	            ret = `>=${M}.${m}.${p} <${+M + 1}.0.0-0`
238	          }
239	        }
240	        return ret
241	      })).join(' ')
242	
243	      // ~, ~> --> * (any, kinda silly)
244	      // ~2, ~2.x, ~2.x.x, ~>2, ~>2.x ~>2.x.x --> >=2.0.0 <3.0.0-0
245	      // ~2.0, ~2.0.x, ~>2.0, ~>2.0.x --> >=2.0.0 <2.1.0-0
246	      // ~1.2, ~1.2.x, ~>1.2, ~>1.2.x --> >=1.2.0 <1.3.0-0
247	      // ~1.2.3, ~>1.2.3 --> >=1.2.3 <1.3.0-0
248	      // ~0.0.1 --> >=0.0.1 <0.1.0-0
249	      comp = comp.trim().split(/\s+/).map((c) => c.replace(loose ? TILDELOOSE_RE : TILDE_RE, (_, M, m, p, pr) => {
250	        let ret
251	        if (!M || M.toLowerCase() === 'x' || M === '*') {
252	          ret = ''
253	        } else if (!m || m.toLowerCase() === 'x' || m === '*') {
254	          ret = `>=${M}.0.0${z} <${+M + 1}.0.0-0`
255	        } else if (!p || p.toLowerCase() === 'x' || p === '*') {
256	          ret = `>=${M}.${m}.0${z} <${M}.${+m + 1}.0-0`
257	        } else if (pr) {
258	          ret = `>=${M}.${m}.${p}-${pr} <${M}.${+m + 1}.0-0`
259	        } else {
260	          ret = `>=${M}.${m}.${p} <${M}.${+m + 1}.0-0`
261	        }
262	        return ret
263	      })).join(' ')
264	
265	      // 1.x, >=1.2.x, <1.x etc
266	      comp = comp.split(/\s+/).map((c) => {
267	        c = c.trim()
268	        return c.replace(loose ? XRANGELOOSE_RE : XRANGE_RE, (ret, gtlt, M, m, p, pr) => {
269	          const xM = !M || M.toLowerCase() === 'x' || M === '*'
270	          const xm = xM || !m || m.toLowerCase() === 'x' || m === '*'
271	          const xp = xm || !p || p.toLowerCase() === 'x' || p === '*'
272	          if ((xM && !(!m || m.toLowerCase() === 'x' || m === '*')) ||
273	            ((!m || m.toLowerCase() === 'x' || m === '*') && p && !(p.toLowerCase() === 'x' || p === '*'))) {
274	            return c
275	          }
276	
277	          if (gtlt === '=' && xp) {
278	            gtlt = ''
279	          }
280	
281	          // if we're including prereleases in the match, then we need
282	          // to fix this to -0, the lowest possible prerelease value
283	          pr = incPr ? '-0' : ''
284	
285	          if (xM) {
286	            if (gtlt === '>' || gtlt === '<') {
287	              // nothing is allowed
288	              ret = '<0.0.0-0'
289	            } else {
290	              // nothing is forbidden
291	              ret = '*'
292	            }
293	          } else if (gtlt && xp) {
294	            // we know patch is an x, because we have any x at all.
295	            // replace X with 0
296	            if (xm) {
297	              m = 0
298	            }
299	            p = 0
300	
301	            if (gtlt === '>') {
302	              // >1 => >=2.0.0
303	              // >1.2 => >=1.3.0
304	              gtlt = '>='
305	              if (xm) {
306	                M = +M + 1
307	                m = 0
308	                p = 0
309	              } else {
310	                m = +m + 1
311	                p = 0
312	              }
313	            } else if (gtlt === '<=') {
314	              // <=0.7.x is actually <0.8.0, since any 0.7.x should
315	              // pass.  Similarly, <=7.x is actually <8.0.0, etc.
316	              gtlt = '<'
317	              if (xm) {
318	                M = +M + 1
319	              } else {
320	                m = +m + 1
321	              }
322	            }
323	
324	            if (gtlt === '<') {
325	              pr = '-0'
326	            }
327	
328	            ret = `${gtlt + M}.${m}.${p}${pr}`
329	          } else if (xm) {
330	            ret = `>=${M}.0.0${pr} <${+M + 1}.0.0-0`
331	          } else if (xp) {
332	            ret = `>=${M}.${m}.0${pr} <${M}.${+m + 1}.0-0`
333	          }
334	          return ret
335	        })
336	      }).join(' ')
337	
338	      // Because * is AND-ed with everything else in the comparator,
339	      // and '' means "any version", just remove the *s entirely.
340	      comp = comp.trim().replace(/(<|>)?=?\s{0,1}\*/, '')
341	      parts.push(comp)
342	    }
343	
344	    let rangeList = parts.join(' ').split(/\s+/).map((comp) => {
345	      // >=0.0.0 is equivalent to *
346	      return comp.trim().replace(incPr ? /^\s{0,1}>=\s{0,1}0\.0\.0-0\s{0,1}$/ : /^\s{0,1}>=\s{0,1}0\.0\.0\s{0,1}$/, '')
347	    })
348	
349	    if (loose) {
350	      // in loose mode, throw out any that are not valid comparators
351	      rangeList = rangeList.filter(comp => !!comp.match(COMPARATORLOOSE_RE))
352	    }
353	
354	    // if any comparators are the null set, then replace with JUST null set
355	    // if more than one comparator, remove any * comparators
356	    // also, don't include the same comparator more than once
357	    const rangeMap = new Map()
358	    const comparators = rangeList.map(comp => new Comparator(comp, this.options))
359	    for (const comp of comparators) {
360	      if (comp.value === '<0.0.0-0') {
361	        return [comp]
362	      }
363	      rangeMap.set(comp.value, comp)
364	    }
365	    if (rangeMap.size > 1 && rangeMap.has('')) {
