'use strict'

const debug = require('../internal/debug')

const NUM = '0|[1-9]\\d{0,256}'
const NUMLOOSE = '\\d{1,256}'
const NONNUM = '\\d{0,256}[a-zA-Z-][a-zA-Z0-9-]{0,250}'
const PREID = '(?:' + NONNUM + '|' + NUM + ')'
const PREIDLOOSE = '(?:' + NONNUM + '|' + NUMLOOSE + ')'
const PRE = '(?:-(' + PREID + '(?:\\.' + PREID + ')*))'
const PRELOOSE = '(?:-?(' + PREIDLOOSE + '(?:\\.' + PREIDLOOSE + ')*))'
const BUILD = '(?:\\+([a-zA-Z0-9-]{1,250}(?:\\.[a-zA-Z0-9-]{1,250})*))'
const FULLPLAIN = 'v?(' + NUM + ')\\.(' + NUM + ')\\.(' + NUM + ')' + PRE + '?' + BUILD + '?'
const LOOSEPLAIN = '[v=\\s]*(' + NUMLOOSE + ')\\.(' + NUMLOOSE + ')\\.(' + NUMLOOSE + ')' + PRELOOSE + '?' + BUILD + '?'

const FULL_RE = new RegExp('^' + FULLPLAIN + '$')
const LOOSE_RE = new RegExp('^' + LOOSEPLAIN + '$')
const PRE_RE = new RegExp(PRE)
const PRELOOSE_RE = new RegExp(PRELOOSE)

const isPrereleaseIdentifier = (prerelease, identifier) => {
  const identifiers = identifier.split('.')
  if (identifiers.length > prerelease.length) {
    return false
  }

  for (let i = 0; i < identifiers.length; i++) {
    let a = prerelease[i]
    let b = identifiers[i]
    let c
    if (typeof a === 'number' && typeof b === 'number') {
      c = a === b ? 0 : a < b ? -1 : 1
    } else {
      const anum = /^[0-9]+$/.test(a)
      const bnum = /^[0-9]+$/.test(b)
      if (anum && bnum) {
        a = +a
        b = +b
      }
      c = a === b ? 0 : (anum && !bnum) ? -1 : (bnum && !anum) ? 1 : a < b ? -1 : 1
    }
    if (c !== 0) {
      return false
    }
  }

  return true
}

