const fs = require('fs')
const path = require('path')

// Simple test runner to verify basic functionality
const satisfies = require('./functions/satisfies')
const Range = require('./classes/range')
const maxSatisfying = require('./ranges/max-satisfying')
const minSatisfying = require('./ranges/min-satisfying')

let testCount = 0
let passCount = 0

function assert(condition, message) {
  testCount++
  if (condition) {
    passCount++
    console.log(`✓ ${message}`)
  } else {
    console.log(`✗ ${message}`)
  }
}

console.log('Running tests...\n')

// Test original behavior is preserved (without prereleaseTags)
console.log('=== Testing original behavior (without prereleaseTags) ===')
assert(satisfies('1.2.3', '^1.2.0'), 'regular version matches range')
assert(!satisfies('1.3.0-rc.1', '^1.2.0'), 'prerelease without explicit option does not match')
assert(satisfies('1.3.0-rc.1', '^1.2.0', { includePrerelease: true }), 'prerelease with includePrerelease matches')
assert(!satisfies('2.0.0', '^1.2.0'), 'version outside range does not match')

// Test new prereleaseTags functionality
console.log('\n=== Testing new prereleaseTags functionality ===')
assert(satisfies('1.3.0-rc.1', '^1.2.0', { prereleaseTags: ['rc'] }), 'rc prerelease matches with rc in prereleaseTags')
assert(!satisfies('1.3.0-beta.1', '^1.2.0', { prereleaseTags: ['rc'] }), 'beta prerelease does not match with only rc in prereleaseTags')
assert(!satisfies('2.0.0-rc.1', '^1.2.0', { prereleaseTags: ['rc'] }), 'rc prerelease outside range does not match')
assert(satisfies('1.3.0-rc.1', '^1.2.0', { prereleaseTags: ['beta', 'rc'] }), 'rc prerelease matches with multiple tags')
assert(satisfies('1.3.0-beta.1', '^1.2.0', { prereleaseTags: ['beta', 'rc'] }), 'beta prerelease matches with multiple tags')

// Test Range#test method
console.log('\n=== Testing Range#test method ===')
const range1 = new Range('^1.2.0', { prereleaseTags: ['rc'] })
assert(range1.test('1.3.0-rc.1'), 'Range#test with prereleaseTags works')
assert(!range1.test('1.3.0-beta.1'), 'Range#test rejects non-matching prerelease tags')

// Test maxSatisfying
console.log('\n=== Testing maxSatisfying ===')
const versions = ['1.2.0', '1.3.0-rc.1', '1.3.0-beta.1', '1.4.0']
const max = maxSatisfying(versions, '^1.2.0', { prereleaseTags: ['rc'] })
assert(max === '1.4.0', `maxSatisfying returns highest version (${max} === 1.4.0)`)

const versions2 = ['1.3.0-rc.1', '1.3.0-rc.2', '1.3.0-beta.1']
const max2 = maxSatisfying(versions2, '^1.2.0', { prereleaseTags: ['rc'] })
assert(max2 === '1.3.0-rc.2', `maxSatisfying returns highest rc version (${max2} === 1.3.0-rc.2)`)

// Test minSatisfying
console.log('\n=== Testing minSatisfying ===')
const min = minSatisfying(versions, '^1.2.0', { prereleaseTags: ['rc'] })
assert(min === '1.2.0', `minSatisfying returns lowest version (${min} === 1.2.0)`)

const min2 = minSatisfying(versions2, '^1.2.0', { prereleaseTags: ['rc'] })
assert(min2 === '1.3.0-rc.1', `minSatisfying returns lowest rc version (${min2} === 1.3.0-rc.1)`)

// Test interaction between includePrerelease and prereleaseTags
console.log('\n=== Testing interaction with includePrerelease ===')
assert(satisfies('1.3.0-alpha.1', '^1.2.0', { includePrerelease: true }), 'includePrerelease allows any prerelease')
assert(satisfies('1.3.0-alpha.1', '^1.2.0', { prereleaseTags: ['alpha', 'rc'] }), 'prereleaseTags allows specified prelease')

// Test with empty array
console.log('\n=== Testing edge cases ===')
assert(!satisfies('1.3.0-rc.1', '^1.2.0', { prereleaseTags: [] }), 'empty prereleaseTags array does not match')
assert(satisfies('1.2.0', '^1.2.0', { prereleaseTags: ['rc'] }), 'non-prerelease versions still match')

console.log(`\n=== Results ===`)
console.log(`${passCount}/${testCount} tests passed`)
if (passCount === testCount) {
  console.log('All tests passed! ✓')
  process.exit(0)
} else {
  console.log(`${testCount - passCount} tests failed! ✗`)
  process.exit(1)
}

