const satisfies = require('./functions/satisfies')
const Range = require('./classes/range')
const maxSatisfying = require('./ranges/max-satisfying')
const minSatisfying = require('./ranges/min-satisfying')
const outside = require('./ranges/outside')
const gtr = require('./ranges/gtr')
const ltr = require('./ranges/ltr')

console.log('Final comprehensive test of prereleaseTags feature:\n')

let passed = 0
let total = 0

const test = (desc, fn) => {
  total++
  try {
    if (fn()) {
      console.log(`✓ ${desc}`)
      passed++
    } else {
      console.log(`✗ ${desc}`)
    }
  } catch (e) {
    console.log(`✗ ${desc} (error: ${e.message})`)
  }
}

// Basic functionality
test('satisfies: rc matches with prereleaseTags', () =>
  satisfies('1.3.0-rc.1', '^1.2.0', { prereleaseTags: ['rc'] }) === true)

test('satisfies: beta does not match rc tags', () =>
  satisfies('1.3.0-beta.1', '^1.2.0', { prereleaseTags: ['rc'] }) === false)

test('satisfies: outside range does not match', () =>
  satisfies('2.0.0-rc.1', '^1.2.0', { prereleaseTags: ['rc'] }) === false)

// Range#test method
test('Range#test: works with prereleaseTags', () => {
  const r = new Range('^1.2.0', { prereleaseTags: ['rc'] })
  return r.test('1.3.0-rc.1') === true && r.test('1.3.0-beta.1') === false
})

// maxSatisfying
test('maxSatisfying: includes rc versions in results', () => {
  const versions = ['1.2.0', '1.3.0-rc.1', '1.3.0-beta.1', '1.4.0']
  return maxSatisfying(versions, '^1.2.0', { prereleaseTags: ['rc'] }) === '1.4.0'
})

test('maxSatisfying: picks highest rc among matching versions', () => {
  const versions = ['1.3.0-rc.1', '1.3.0-rc.3', '1.3.0-rc.2']
  return maxSatisfying(versions, '^1.2.0', { prereleaseTags: ['rc'] }) === '1.3.0-rc.3'
})

// minSatisfying
test('minSatisfying: includes rc versions in results', () => {
  const versions = ['1.2.0', '1.3.0-rc.1', '1.3.0-beta.1', '1.4.0']
  return minSatisfying(versions, '^1.2.0', { prereleaseTags: ['rc'] }) === '1.2.0'
})

test('minSatisfying: picks lowest rc among rc versions', () => {
  const versions = ['1.3.0-rc.3', '1.3.0-rc.1', '1.3.0-rc.2']
  return minSatisfying(versions, '^1.2.0', { prereleaseTags: ['rc'] }) === '1.3.0-rc.1'
})

// outside, gtr, ltr
test('outside/gtr: works with prereleaseTags', () =>
  gtr('1.3.0-rc.1', '^1.2.0', { prereleaseTags: ['rc'] }) === false)

test('outside/ltr: works with prereleaseTags', () =>
  ltr('1.3.0-rc.1', '^1.2.0', { prereleaseTags: ['rc'] }) === false)

// Edge cases
test('prereleaseTags: empty array does not match', () =>
  satisfies('1.3.0-rc.1', '^1.2.0', { prereleaseTags: [] }) === false)

test('prereleaseTags: multiple tags work', () => {
  const opts = { prereleaseTags: ['alpha', 'beta', 'rc'] }
  return satisfies('1.3.0-rc.1', '^1.2.0', opts) === true &&
         satisfies('1.3.0-beta.1', '^1.2.0', opts) === true &&
         satisfies('1.3.0-alpha.1', '^1.2.0', opts) === true
})

test('prereleaseTags: non-prerelease versions still match', () =>
  satisfies('1.3.0', '^1.2.0', { prereleaseTags: ['rc'] }) === true)

// Backward compatibility
test('without prereleaseTags: original behavior preserved', () =>
  satisfies('1.3.0-rc.1', '^1.2.0') === false)

test('includePrerelease: overrides prereleaseTags', () =>
  satisfies('1.3.0-beta.1', '^1.2.0', { includePrerelease: true }) === true)

// Range caching test
test('Range caching: different prereleaseTags create different instances', () => {
  const r1 = new Range('^1.2.0', { prereleaseTags: ['rc'] })
  const r2 = new Range(r1, { prereleaseTags: ['beta'] })
  return r1 !== r2 && r1.test('1.3.0-rc.1') === true && r2.test('1.3.0-beta.1') === true
})

console.log(`\n${passed}/${total} tests passed`)
process.exit(passed === total ? 0 : 1)

